-- 2) Posts (reaction_count starts at 0; recomputed at the end so the trigger can't double-count).

-- 3) Reactions.

-- 4) Set each post's reaction_count to the true number of reactions (trigger-independent).
update public.posts p set reaction_count = coalesce(sub.c,0)
  from (select post_id, count(*) c from public.reactions group by post_id) sub
 where p.id = sub.post_id;

commit;
